    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    groups = [(props.get(x.get('element')) or {}).get('group') for x in sites]
    ens = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    rows = [(props.get(x.get('element')) or {}).get('row') for x in sites]
    acceptor = [groups[i] is not None and ens[i] is not None and 14 <= groups[i] <= 17 and ens[i] >= 2.0 for i in range(n)]
    partner = [ens[i] is not None and ens[i] >= 2.0 and (acceptor[i] or (groups[i] == 1 and rows[i] == 1)) for i in range(n)]
    bond_sum = [0.0 for i in range(n)]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0):
            continue
        if not acceptor[i] or not partner[j] or occ[i] * occ[j] <= 0.0:
            continue
        radius_sum = radii[i] + radii[j]
        if d <= 1.3 * radius_sum:
            ratio = min(2.0, radius_sum / d)
            bond_sum[i] += occ[j] * min(3.0, ratio ** 6)
    total = 0.0
    for i in range(n):
        if acceptor[i]:
            total += occ[i] * max(0.0, 18.0 - groups[i] - bond_sum[i])
    return total / max(sum(occ), 1e-12)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    if n == 0:
        return 0.0
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    parent = list(range(n))
    shift = [[0, 0, 0] for i in range(n)]
    gram = [[0.0 for k in range(6)] for i in range(n)]
    for bond in s.get('neighbors') or []:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0):
            continue
        if occ[i] * occ[j] <= 0.0 or d > 1.3 * (radii[i] + radii[j]):
            continue
        image = bond.get('image') or [0, 0, 0]
        if len(image) != 3:
            continue
        ri = i
        ai = [0, 0, 0]
        for step in range(n):
            if parent[ri] == ri:
                break
            for k in range(3):
                ai[k] += shift[ri][k]
            ri = parent[ri]
        rj = j
        aj = [0, 0, 0]
        for step in range(n):
            if parent[rj] == rj:
                break
            for k in range(3):
                aj[k] += shift[rj][k]
            rj = parent[rj]
        cycle = [ai[k] + image[k] - aj[k] for k in range(3)]
        if ri != rj:
            parent[rj] = ri
            shift[rj] = cycle
            for k in range(6):
                gram[ri][k] += gram[rj][k]
        else:
            x, y, z = cycle
            gram[ri][0] += x * x
            gram[ri][1] += y * y
            gram[ri][2] += z * z
            gram[ri][3] += x * y
            gram[ri][4] += x * z
            gram[ri][5] += y * z
    masses = [0.0 for i in range(n)]
    for i in range(n):
        root = i
        for step in range(n):
            if parent[root] == root:
                break
            root = parent[root]
        masses[root] += occ[i]
    total = 0.0
    for i in range(n):
        if parent[i] != i or masses[i] <= 0.0:
            continue
        xx, yy, zz, xy, xz, yz = gram[i]
        if xx + yy + zz <= 0.0:
            continue
        matrix = np.array([[xx, xy, xz], [xy, yy, yz], [xz, yz, zz]])
        values = np.linalg.eigvalsh(matrix)
        threshold = max(1e-8, values[2] * 1e-8)
        dimension = sum(1 for value in values if value > threshold)
        total += masses[i] * dimension
    return total / max(sum(occ), 1e-12)
